/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var D = {"N": 5, "fx": 207.3, "fy": 103.8, "cx": 197.3, "cy": 127.8};
  phases([[0,12],[12,28],[28,44],[44,80]]);
  v.dO = lin([[0,0],[2,1],[10,1],[12,0]]);
  for (var i = 0; i < 3; i++) v['dc'+i] = p >= 3 + i * 2 ? 1 : 0;
  v.geoO = (p < 30 ? 1 : 1 - 0.35 * lin([[30,0],[33,1]])) * out;
  v.scanO = (p >= 12 && p < 26) ? 1 : 0; v.scanY = (lin([[12,0],[26,1]]) * 286).toFixed(1);
  for (var i = 0; i < D.N; i++) v['g'+i] = (p >= 14 + i * 2.4 && p < 97) ? out : 0;
  v.tbO = lin([[28,0],[30,1]]) * out;
  for (var i = 0; i < D.N; i++) { var t = 31 + i * 2, f = lin([[t,0],[t+1.5,1]]); v['f'+i] = 'opacity: ' + ((f > 0.01 ? 1 : 0) * out) + '; transform: translateY(' + (-10 * (1 - f)).toFixed(1) + 'px);'; }
  var mx = lin([[44,380],[52,D.fx]]), my = lin([[44,260],[52,D.fy]]);
  v.cur = 'opacity: ' + ((p >= 44 && p < 97) ? out : 0) + '; transform: translate(' + mx.toFixed(1) + 'px,' + my.toFixed(1) + 'px);';
  v.rpO = (p >= 53 && p < 57) ? 1 - (p - 53) / 4 : 0; v.rpR = (6 + (p >= 53 ? (p - 53) * 5 : 0)).toFixed(1);
  v.sel = (p >= 53 && p < 97) ? out : 0;
  v.pfO = (p >= 54 && p < 97) ? out : 0; v.pvO = 1 - v.pfO;
  v.sumO = (p >= 70 && p < 97) ? out : 0;
  var zf = lin([[55,0],[63,1]]), Z = 2.6, zs = 1 + (Z - 1) * zf;
  var tx = D.cx + (196 - D.cx) * zf - zs * D.cx, ty = D.cy + (150 - D.cy) * zf - zs * D.cy;
  v.zoom = 'transform-origin: 0 0; transform: translate(' + tx.toFixed(1) + 'px,' + ty.toFixed(1) + 'px) scale(' + zs.toFixed(3) + ');';
  v.zlO = (p >= 63 && p < 97) ? out : 0;
  if (p >= 55) v.cur = 'opacity: 0; transform: translate(0px,0px);';

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
